-- MC-D01: extend new meal-plan document captures with already stored prescription
-- measures, substitution portions, notes, composition and alternative flags.
-- No UPDATE of historical artifacts, signatures, hashes, prescriptions or accounts.
-- CREATE OR REPLACE preserves owner/ACL; authorization, active actor, visibility,
-- professional identity and duplicate-document guards remain unchanged.
CREATE OR REPLACE FUNCTION public.create_document_artifact_from_meal_plan(p_plan_id bigint, p_visibility text DEFAULT 'shared_with_patient'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_actor uuid:=auth.uid();v_plan public.meal_plans%rowtype;v_episode public.care_episodes%rowtype;v_identity public.professional_document_identities%rowtype;v_responsible uuid;v_id uuid;v_payload jsonb;begin
 perform private.wave05_require_active_actor();
 if v_actor is null then raise exception using errcode='42501',message='authentication_required';end if;if p_visibility not in('professional_private','shared_with_patient','share_later')then raise exception using errcode='22023',message='invalid_document_visibility';end if;select*into v_plan from public.meal_plans where id=p_plan_id;select*into v_episode from public.care_episodes where id=v_plan.care_episode_id;if v_plan.id is null or v_plan.is_draft or v_plan.prescription_status in('archived','invalidated')or not private.can_write_active_care_episode(v_plan.care_episode_id)or v_actor not in(v_plan.nutritionist_id,coalesce(v_episode.student_id,v_plan.nutritionist_id),coalesce(v_episode.supervisor_id,v_plan.nutritionist_id))then raise exception using errcode='42501',message='meal_plan_document_forbidden';end if;v_responsible:=coalesce(v_episode.supervisor_id,v_plan.nutritionist_id);select*into v_identity from public.professional_document_identities where professional_id=v_responsible and status='active';if not found then raise exception using errcode='23514',message='responsible_document_identity_required';end if;if exists(select 1 from public.document_artifacts where source_type='meal_plan'and source_key=p_plan_id::text and status in('draft','finalized','signed'))then raise exception using errcode='23505',message='meal_plan_document_already_exists';end if;select jsonb_build_object('title','PLANO ALIMENTAR','plan_name',v_plan.name,'issued_on',current_date,'diet_characteristics',jsonb_strip_nulls(jsonb_build_object('mode',v_plan.plan_mode,'description',v_plan.description,'active_days',v_plan.active_days,'start_date',v_plan.start_date,'end_date',v_plan.end_date)),'nutritional_targets',jsonb_build_object('energy_kcal',v_plan.daily_calories,'protein_g',v_plan.daily_protein,'carbohydrate_g',v_plan.daily_carbs,'fat_g',v_plan.daily_fat),'meals',coalesce((select jsonb_agg(jsonb_build_object('name',m.name,'type',m.meal_type,'time',m.meal_time,'notes',m.notes,'include_in_totals',m.include_in_totals,'foods',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',coalesce(f.food_snapshot->>'name',fd.name),'quantity',f.quantity,'unit',f.unit,'patient_description',f.patient_description,'calories',f.calories,'protein',f.protein,'carbs',f.carbs,'fat',f.fat,'notes',f.notes,'food_snapshot',f.food_snapshot,'measure_snapshot',f.measure_snapshot,'substitutes',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',coalesce(s.food_snapshot->>'name',sf.name),'quantity',s.quantity,'unit',s.unit,'notes',s.notes,'food_snapshot',s.food_snapshot,'measure_snapshot',s.measure_snapshot)) order by s.id) from public.meal_plan_food_substitutions s left join public.foods sf on sf.id=s.substitute_food_id where s.meal_plan_food_id=f.id),'[]'::jsonb),'source',coalesce(f.food_snapshot->>'source',fd.source)))order by f.order_index,f.id)from public.meal_plan_foods f left join public.foods fd on fd.id=f.food_id where f.meal_plan_meal_id=m.id),'[]'::jsonb))order by m.order_index,m.id)from public.meal_plan_meals m where m.meal_plan_id=v_plan.id),'[]'::jsonb),'professional_confirmation',jsonb_build_object('responsible_id',v_responsible,'prepared_by',v_actor),'source_snapshot',v_plan.source_snapshot)into v_payload;insert into public.document_artifacts(layout_code,layout_version,source_type,source_key,patient_id,care_episode_id,professional_id,preparer_id,supervisor_id,identity_id,visibility,draft_payload)values('meal_plan',1,'meal_plan',p_plan_id::text,v_plan.patient_id,v_plan.care_episode_id,v_responsible,v_actor,v_episode.supervisor_id,v_identity.id,p_visibility,v_payload)returning id into v_id;insert into public.document_artifact_events(artifact_id,actor_id,event_type,to_status,reason)values(v_id,v_actor,'created','draft','document_created_from_meal_plan');return jsonb_build_object('artifact_id',v_id,'status','draft','revision',1,'source_key',p_plan_id::text);end$function$;
